document.addEventListener("DOMContentLoaded",function(){var e=document.getElementById("offerCountdown").textContent,a=new Date(e).getTime();setInterval(function(){var e=(new Date).getTime(),e=a-e,n=Math.floor(e/864e5),t=Math.floor(e%864e5/36e5),o=Math.floor(e%36e5/6e4),e=Math.floor(e%6e4/1e3);document.getElementById("countdowntimer").innerHTML=`<ul>
                <li><span id="days">${n}</span></li>
                <li><span id="hours">${t}</span></li>
                <li><span id="minutes">${o}</span></li>
                <li><span id="seconds">${e}</span></li>
            </ul>`},1e3)});